import random

def get_girth(adj, n):
    for i in range(n):
        # BFS to find the shortest cycle containing i
        dist = [-1] * n
        dist[i] = 0
        queue = [i]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
                elif dist[v] >= dist[u]:
                    # Cycle found
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < 7:
                        return cycle_len
    return 100 # Large enough

def solve():
    n = 23
    adj = [set() for _ in range(n)]
    edges = []

    # Try to build a 3-regular graph
    # A 3-regular graph has 23*3/2 = 34.5 edges, which is impossible.
    # So it must have some vertices with degree 4.
    # Let's aim for a graph where most vertices have degree 3 or 4.

    # Let's try a randomized approach
    for _ in range(100000):
        # Reset
        adj = [set() for _ in range(n)]
        edges = []

        # Try to add edges
        # We need at least 23*3/2 = 34.5 edges, so at least 35 edges.
        # Let's try to add 35 edges.

        possible_edges = []
        for i in range(n):
            for j in range(i + 1, n):
                possible_edges.append((i, j))
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            if len(adj[u]) < 7 and len(adj[v]) < 7:
                # Check if adding (u, v) creates a cycle < 7
                adj[u].add(v)
                adj[v].add(u)
                if get_girth(adj, n) < 7:
                    adj[u].remove(v)
                    adj[v].remove(u)
                else:
                    edges.append((u, v))

            # Check if we have enough edges and all degrees >= 3
            if len(edges) >= 35:
                all_degrees_ok = True
                for i in range(n):
                    if len(adj[i]) < 3:
                        all_degrees_ok = False
                        break
                if all_degrees_ok:
                    return edges
    return None

result = solve()
print(result)
